      "content": "from __future__ import annotations

from typing import List, Sequence, Tuple

from stockflow.parse_location import parse_location


def pick_route_order(picks: Sequence[Tuple[str, str, int]]) -> List[Tuple[str, str, int]]:
    """
    Sort pick lines into the picker's walking order.

    Picks are sorted by zone, then by aisle in a serpentine (S-shaped) pattern:
    - Odd-numbered aisles are walked in ascending shelf order.
    - Even-numbered aisles are walked in descending shelf order.
    - Within each shelf, levels are always sorted in ascending order.

    Args:
        picks: A sequence of (sku, location, quantity) tuples.

    Returns:
        A list of (sku, location, quantity) tuples sorted in walking order.
    """
    def route_key(pick: Tuple[str, str, int]) -> Tuple[str, int, int, int]:
        zone, aisle, shelf, level = parse_location(pick[1])
        along = shelf if aisle % 2 == 1 else -shelf
        return (zone, aisle, along, level)

    return sorted(picks, key=route_key)
"
